import{_ as d,o as e,c as o,a2 as c}from"./chunks/framework.B4hAkGey.js";const u=JSON.parse('{"title":"漫画剧场风格规范 · 霓虹墨 Neon Ink（WebRTC × 5G 版）v1.0","description":"","frontmatter":{},"headers":[],"relativePath":"comics/style-guide.md","filePath":"comics/style-guide.md","lastUpdated":1792683941000}'),a={name:"comics/style-guide.md"};function r(l,t,i,n,s,h){return e(),o("div",null,[...t[0]||(t[0]=[c('<h1 id="漫画剧场风格规范-·-霓虹墨-neon-ink-webrtc-×-5g-版-v1-0" tabindex="-1">漫画剧场风格规范 · 霓虹墨 Neon Ink（WebRTC × 5G 版）v1.0 <a class="header-anchor" href="#漫画剧场风格规范-·-霓虹墨-neon-ink-webrtc-×-5g-版-v1-0" aria-label="Permalink to &quot;漫画剧场风格规范 · 霓虹墨 Neon Ink（WebRTC × 5G 版）v1.0&quot;">​</a></h1><blockquote><p>本规范是 <code>comics/</code> 全部漫画的唯一视觉与叙事标准，与 <code>threejs-tutorial</code> 漫画剧场共用同一套霓虹墨视觉体系与三角色设定。 新增或修改任何一话，都必须对照本文档执行。 校验入口：<code>pnpm run comics:check</code>（manifest 一致性 + SVG 良构性 + 文本溢出启发式 + MD 完整性）。</p></blockquote><h2 id="_1-画布与分格" tabindex="-1">1. 画布与分格 <a class="header-anchor" href="#_1-画布与分格" aria-label="Permalink to &quot;1. 画布与分格&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项</th><th>规定</th></tr></thead><tbody><tr><td>画布</td><td><code>viewBox=&quot;0 0 1200 840&quot;</code>，深墨底渐变（左上 <code>#0b1220</code> → 右下 <code>#101a33</code>）</td></tr><tr><td>分格</td><td>2×2 四格，面板尺寸 <strong>572×361</strong>，圆角 14</td></tr><tr><td>面板坐标</td><td>左上 <code>(20,84)</code>、右上 <code>(608,84)</code>、左下 <code>(20,462)</code>、右下 <code>(608,462)</code></td></tr><tr><td>页眉</td><td>EP 徽章（<code>#7C3AED</code> 圆角矩形 92×36）+ 标题（渐变字 26px）+ 右侧系列名；页眉下 1160×2 渐变分隔线（y=62）</td></tr><tr><td>页脚</td><td>右下角 11px 水印 <code>NEON INK · webrtc-5g-tutorial · EP.NN</code>（色 <code>#475569</code>）</td></tr><tr><td>装饰</td><td>每格 1~2 条斜切光楔（多边形，霓虹色 opacity ≤0.05），禁止高不透明度大色块</td></tr></tbody></table><h2 id="_2-色板-60-30-10" tabindex="-1">2. 色板（60/30/10） <a class="header-anchor" href="#_2-色板-60-30-10" aria-label="Permalink to &quot;2. 色板（60/30/10）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>用途</th><th>色值</th></tr></thead><tbody><tr><td>底色（60%）</td><td><code>#0b1220</code> <code>#101a33</code> <code>#0e1730</code>（面板）</td></tr><tr><td>结构线/弱文本（30%）</td><td><code>#1e2a44</code> <code>#223055</code> <code>#64748b</code> <code>#94a3b8</code> <code>#e2e8f0</code></td></tr><tr><td>霓虹强调（10%）</td><td>青 <code>#22d3ee</code> / 紫 <code>#7C3AED</code> <code>#a78bfa</code> / 品红 <code>#f472b6</code> / 橙 <code>#f97316</code> / 绿 <code>#34d399</code> / 黄 <code>#fbbf24</code></td></tr><tr><td>面板编号色</td><td>1=青、2=紫、3=品红、4=橙</td></tr></tbody></table><p><strong>WebRTC 语义色约定</strong>（全系列保持一致）：</p><ul><li>信令协商：青 <code>#22d3ee</code></li><li>媒体管线 / SDP：紫 <code>#a78bfa</code></li><li>网络传输 / 拥塞：橙 <code>#f97316</code></li><li>ICE / STUN / TURN：绿 <code>#34d399</code></li><li>直播推拉流：品红 <code>#f472b6</code></li><li>5G 特性 / URLLC：黄 <code>#fbbf24</code></li></ul><p>对比度规则：气泡为浅底（<code>#f8fafc</code>）配深字（<code>#0b1220</code>）；深底上正文用 <code>#e2e8f0</code>；强调词单独 <code>&lt;tspan&gt;</code> 换霓虹色。所有文字对比度 ≥ 4.5:1。</p><h2 id="_3-字号阶梯与字体" tabindex="-1">3. 字号阶梯与字体 <a class="header-anchor" href="#_3-字号阶梯与字体" aria-label="Permalink to &quot;3. 字号阶梯与字体&quot;">​</a></h2><table tabindex="0"><thead><tr><th>元素</th><th>字号</th><th>字色</th></tr></thead><tbody><tr><td>话标题</td><td>26 bold</td><td>渐变（青→紫）</td></tr><tr><td>面板标题</td><td>17 bold</td><td><code>#e2e8f0</code></td></tr><tr><td>气泡正文</td><td>15~16</td><td><code>#0b1220</code>（浅底）</td></tr><tr><td>代码</td><td>12~13 mono</td><td><code>#7dd3fc</code> / <code>#fbbf24</code> / <code>#34d399</code> / <code>#f472b6</code></td></tr><tr><td>注脚/水印</td><td>11~12</td><td><code>#64748b</code></td></tr></tbody></table><ul><li><code>font-family=&quot;&#39;PingFang SC&#39;,&#39;Hiragino Sans GB&#39;,&#39;Microsoft YaHei&#39;,sans-serif&quot;</code>；代码用 <code>&#39;SF Mono&#39;,&#39;JetBrains Mono&#39;,Consolas,monospace</code>。</li><li><strong>每个 <code>&lt;text&gt;</code>/<code>&lt;tspan&gt;</code> 必须显式写 <code>font-size</code></strong>（校验脚本依赖）。</li><li>气泡单行 ≤ 17 个汉字（约 272px），代码单行 ≤ 40 字符。</li></ul><h2 id="_4-组件规范" tabindex="-1">4. 组件规范 <a class="header-anchor" href="#_4-组件规范" aria-label="Permalink to &quot;4. 组件规范&quot;">​</a></h2><ul><li><strong>气泡</strong>：圆角 10 浅底矩形 + 小三角尾巴指向说话人；尾巴必须连到头像。</li><li><strong>头像（半身 44px 级）</strong>：头圆 r≈17 + 发型 + 眼睛两点 + 微笑弧 + 身体圆角矩形。</li><li><strong>代码芯片</strong>：深底 <code>#0a0f1c</code>、描边霓虹色（opacity 0.35）、圆角 8、内边距 ≥12；代码中的 <code>&lt;</code>/<code>&gt;</code> 必须写 <code>&amp;lt;</code>/<code>&amp;gt;</code>。</li><li><strong>底部结论条</strong>：圆角矩形 <code>#111a30</code> + 左侧 4px 霓虹竖条，两行 13.5px。</li><li><strong>坑点标签</strong>：橙 <code>#f97316</code> 小圆角条 + &quot;⚠ 坑点&quot; 前缀，只出现在第 4 格。</li><li><strong>转义</strong>：文本中 <code>&lt;</code> → <code>&amp;lt;</code>、<code>&gt;</code> → <code>&amp;gt;</code>、<code>&amp;</code> → <code>&amp;amp;</code>；禁止在属性值里出现 <code>&gt;</code>。</li></ul><h2 id="_5-三角色设定" tabindex="-1">5. 三角色设定 <a class="header-anchor" href="#_5-三角色设定" aria-label="Permalink to &quot;5. 三角色设定&quot;">​</a></h2><table tabindex="0"><thead><tr><th>角色</th><th>在本系列的人设</th><th>视觉锚点</th></tr></thead><tbody><tr><td>像素酱</td><td>提问担当：参数党、爱追问&quot;为什么 ICE 要收集这么多候选&quot;</td><td>青色高马尾 + 紫色卫衣 + <code>{}</code> 徽章</td></tr><tr><td>标签君</td><td>行动派：接了直播产品需求，踩坑王</td><td>橙色刺猬头 + 蓝外套 + HTML5 盾徽</td></tr><tr><td>码叔</td><td>教授：讲媒体管线、SDP、拥塞控制，负责总结</td><td>白发白须 + 圆框眼镜 + 浅灰大褂 + 指教鞭</td></tr></tbody></table><p>叙事分工：像素酱/标签君负责&quot;又黑屏了 / SDP 协商失败 / 卡成 PPT&quot;的困境与追问，码叔负责&quot;揭示管线、给出参数与最佳实践&quot;。每话至少两角色出场。</p><h2 id="_6-叙事结构-四幕" tabindex="-1">6. 叙事结构（四幕） <a class="header-anchor" href="#_6-叙事结构-四幕" aria-label="Permalink to &quot;6. 叙事结构（四幕）&quot;">​</a></h2><ol><li><strong>第一格 · 困境</strong>：真实开发场景抛出问题（黑屏 / 协商失败 / 穿透失败 / 卡顿）；</li><li><strong>第二格 · 揭秘</strong>：原理拆解，配 1 段迷你代码芯片或管线示意图；</li><li><strong>第三格 · 实证</strong>：对比演示（正确 vs 错误、参数前后对比、流程顺序图示）；</li><li><strong>第四格 · 结案</strong>：最佳实践 + ⚠ 坑点标签（2~3 条）+ 一句码叔总结。</li></ol><p>每格左上角有编号色块（1~4）+ 4~8 字面板标题；整话无对白超过 3 行/气泡。</p><h2 id="_7-命名与文件" tabindex="-1">7. 命名与文件 <a class="header-anchor" href="#_7-命名与文件" aria-label="Permalink to &quot;7. 命名与文件&quot;">​</a></h2><ul><li>一话 = <code>EP.NN-slug.svg</code> + <code>EP.NN-slug.md</code>，NN 两位数，slug 全小写连字符；</li><li>一话严格对应 <code>guide/</code> 下一个模块；</li><li>新增话必须同步：<code>manifest.json</code>、<code>README.md</code> 导航表；</li><li>讲解 MD 结构固定：<code># EP.NN 标题</code> → <code>&gt; 对应正文 / 动手演示</code> → <code>剧情回顾</code> → <code>知识点拆解</code> → <code>坑点清单（FAQ）</code> → <code>自测 3 题（含答案）</code>；</li><li>每话必须链接至少 1 个 <code>public/demos/</code> 下的对应演示。</li></ul>',22)])])}const g=d(a,[["render",r]]);export{u as __pageData,g as default};
